// Webhook経由の場合は $json.body から、Execute Workflow Trigger経由の場合は $json から取得
const rawInput = $input.first().json;
const input = rawInput.body || rawInput;

// notionPageId または script_id の両方に対応
const scriptId = input.notionPageId || input.script_id;

if (!scriptId) {
  throw new Error('script_id or notionPageId is required');
}

// スライド数を1〜7枚に対応
if (!input.slides_metadata || !Array.isArray(input.slides_metadata)) {
  throw new Error('slides_metadata must be an array');
}

if (input.slides_metadata.length < 1 || input.slides_metadata.length > 7) {
  throw new Error('slides_metadata must contain between 1 and 7 items');
}

// 各スライドの必須フィールド確認
for (const slide of input.slides_metadata) {
  if (!slide.image_url) throw new Error(`Missing image_url for ${slide.section}`);
  if (!slide.duration) throw new Error(`Missing duration for ${slide.section}`);
}

// script_idを統一して返す（配列として返す）
return [{
  ...input,
  script_id: scriptId
}];

const input = $input.first().json;
const slides = input.slides_metadata;

if (!slides || slides.length === 0) {
  throw new Error('slides_metadata is empty');
}

// Cloudinary manifest_json構造
const manifest = {
  width: 1920,
  height: 1080,
  fps: 30,
  slides: slides.map(slide => ({
    media: slide.image_url,
    duration: slide.duration
  }))
};

// 合計時間を計算
const totalDuration = slides.reduce((sum, s) => sum + s.duration, 0);

return {
  json: {
    script_id: input.script_id,
    manifest_json: JSON.stringify(manifest),
    slides_metadata: slides,
    total_duration: totalDuration,
    slides_count: slides.length
  }
};

const apiSecret = 'IKxxQL7zniUB5s9TeijsChM8hAs';
const timestamp = Math.floor(Date.now() / 1000);
const manifest_json = $json.manifest_json;

// create_slideshow用の署名生成
const stringToSign = `manifest_json=${manifest_json}&timestamp=${timestamp}${apiSecret}`;

// SHA-1ハッシュ生成
function sha1(str) {
  function rotateLeft(n, s) {
    return (n << s) | (n >>> (32 - s));
  }

  function toHexStr(n) {
    let s = '', v;
    for (let i = 7; i >= 0; i--) {
      v = (n >>> (i * 4)) & 0xf;
      s += v.toString(16);
    }
    return s;
  }

  function utf8Encode(str) {
    return unescape(encodeURIComponent(str));
  }

  let message = utf8Encode(str);
  let msgLen = message.length;
  let words = [];

  for (let i = 0; i < msgLen; i++) {
    words[i >>> 2] |= (message.charCodeAt(i) & 0xff) << (24 - 8 * (i % 4));
  }

  words[msgLen >>> 2] |= 0x80 << (24 - 8 * (msgLen % 4));
  words[(((msgLen + 8) >>> 6) << 4) + 15] = msgLen * 8;

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let i = 0; i < words.length; i += 16) {
    let w = words.slice(i, i + 16);
    for (let j = 16; j < 80; j++) {
      w[j] = rotateLeft(w[j-3] ^ w[j-8] ^ w[j-14] ^ w[j-16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let j = 0; j < 80; j++) {
      let f, k;
      if (j < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (j < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (j < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      let temp = (rotateLeft(a, 5) + f + e + k + (w[j] | 0)) | 0;
      e = d;
      d = c;
      c = rotateLeft(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  return toHexStr(h0) + toHexStr(h1) + toHexStr(h2) + toHexStr(h3) + toHexStr(h4);
}

const signature = sha1(stringToSign);

return {
  json: {
    ...($input.first().json),
    cloudinary_timestamp: timestamp,
    cloudinary_signature: signature
  }
};

const input = $input.first().json;

// エラーハンドリング
if (input.error || !input.secure_url) {
  return [{
    json: {
      success: false,
      error: input.error || 'Video generation failed',
      script_id: $('Code - Build Slideshow Manifest').item.json.script_id || 'unknown'
    }
  }];
}

// 正常時のレスポンス
const manifestData = $('Code - Build Slideshow Manifest').item.json;

return [{
  json: {
    success: true,
    script_id: manifestData.script_id,
    video_url: input.secure_url,
    video_duration: input.duration || manifestData.total_duration,
    video_format: input.format || 'mp4',
    width: input.width || 1920,
    height: input.height || 1080,
    cloudinary_asset_id: input.asset_id,
    cloudinary_public_id: input.public_id,
    slides_count: manifestData.slides_count,
    created_at: input.created_at || new Date().toISOString()
  }
}];
